/* Animations Mat et Flo des écrans d'attente (évacuation, remise des médailles, pause), dessinées image par image en SVG. © Mat-et-Flo */
(function(){const st=document.createElement('style');st.textContent="@font-face{font-family:'Outfit';font-weight:600;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Outfit';font-weight:800;src:url(data:font/woff2;base64,) format('woff2')}";document.head.appendChild(st)})();
(function(){
const NAVY='#12307f', DARK='#0b1f55', RED='#d8343a', CREAM='#f7f5ec';
const TOTAL=18.5;
const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));
const ease=x=>{x=clamp(x);return x*x*(3-2*x)};
const lerp=(a,b,x)=>a+(b-a)*x;
function keys(t,k,lin){
  if(t<=k[0][0]) return k[0].slice(1);
  for(let i=0;i<k.length-1;i++){
    if(t<=k[i+1][0]){
      let u=(t-k[i][0])/(k[i+1][0]-k[i][0]); if(!lin) u=ease(u);
      return k[i].slice(1).map((v,j)=>lerp(v,k[i+1][j+1],u));
    }
  }
  return k[k.length-1].slice(1);
}
function rnd(i){const x=Math.sin(i*127.1+311.7)*43758.5453;return x-Math.floor(x)}
const f=n=>Math.round(n*10)/10;

/* ---------- CIGOGNES DU LOGO MAT-ET-FLO ---------- */
function lstork(o){
  const s=o.s||1, dir=o.dir||1, t=o.t||0, flo=o.who==='flo';
  const pose=o.pose||'stand';
  const INK='#17304f', WING='#1c1f2b', RD='#e0352b';
  const bw=flo?1.2:1, bh=flo?1.22:1;
  const sp=pose==='panic'?18:(pose==='walk'?10:0), ph=t*sp;
  const walking=pose==='walk'||pose==='panic';
  const bob=walking?Math.abs(Math.sin(ph/2))*(pose==='panic'?5:3):0;
  const hop=pose==='panic'?-Math.abs(Math.sin(t*9))*10:0;
  const leg=d=>`<path d="${d}" fill="none" stroke="${RD}" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>`;
  let legs='';
  if(pose==='sit'){
    const L=sx=>leg(`M${sx},-62 L${sx+50},-66 L${sx+88},-84 l12,-4`);
    legs=L(-6)+L(8);
  } else if(pose==='fly'){
    const L=(sx,a)=>leg(`M${sx},-62 L${sx-36},${-56+a} L${sx-76},${-50+a} l-10,0`);
    legs=L(-6,0)+L(8,5);
  } else if(pose!=='swim'){
    const amp=walking?16:0;
    const L=(hx,p)=>{const sw=Math.sin(p)*amp, lift=walking?Math.max(0,Math.cos(p))*10:0;
      return leg(`M${hx},-62 L${f(hx+sw*0.4)},-32 L${f(hx+sw)},${f(-lift)} l12,0`);};
    legs=L(-7,ph)+L(8,ph+Math.PI);
  }
  let flapA=0;
  if(pose==='panic') flapA=-(18+46*Math.abs(Math.sin(t*14)));
  else if(pose==='fly') flapA=-55*Math.sin(t*12)+8;
  else if(o.clap) flapA=-28*Math.abs(Math.sin(t*9));
  const bT=`translate(0 -98) scale(${bw} ${bh}) translate(0 98)`;
  const tail=`<path d="M-30,-98 L-66,-84 L-62,-72 L-28,-80 Z" fill="${WING}" stroke="${INK}" stroke-width="2" stroke-linejoin="round"/>`;
  const body=`<ellipse cx="0" cy="-98" rx="40" ry="30" fill="#fff" stroke="${INK}" stroke-width="3" transform="rotate(-8 0 -98)"/>`;
  const wing=`<g transform="rotate(${f(flapA)} -20 -98)"><path d="M-30,-104 Q4,-124 36,-102 Q12,-72 -34,-84 Z" fill="${WING}"/></g>`;
  const trunk=`<g transform="${bT}">${tail}${body}${wing}</g>`;
  let headRot=(o.head||0)+(walking?Math.sin(ph/2+1)*2.5:0)+(pose==='panic'?Math.sin(t*20)*8:0);
  const neckD='M26,-112 Q44,-130 36,-166';
  const open=o.beak!=null?o.beak:(pose==='panic'?5+6*Math.abs(Math.sin(t*16)):0);
  const beak=open<1?`<path d="M50,-181 L100,-167 L50,-163 Z" fill="${RD}" stroke="${INK}" stroke-width="2.5" stroke-linejoin="round"/>`
    :`<path d="M50,-181 L100,-167 L50,-170 Z" fill="${RD}" stroke="${INK}" stroke-width="2.5" stroke-linejoin="round"/><path d="M50,-170 L96,${f(-163+open)} L50,-163 Z" fill="#b82a30" stroke="${INK}" stroke-width="2.5" stroke-linejoin="round"/>`;
  let face=`<circle cx="43" cy="-177" r="2.8" fill="${INK}"/>`;
  if(flo) face+=`<circle cx="43" cy="-177" r="9" fill="#fff" fill-opacity="0.55" stroke="#111" stroke-width="3.5"/><path d="M34,-177 L24,-181" stroke="#111" stroke-width="3.5" stroke-linecap="round"/><path d="M33,-190 L55,-183" stroke="#111" stroke-width="4" stroke-linecap="round"/>`;
  else face+=`<path d="M27,-186 L25,-203 L33,-195 L38,-208 L44,-195 L51,-203 L49,-186 Z" fill="#cfd5de" stroke="${INK}" stroke-width="2.6" stroke-linejoin="round"/><circle cx="38" cy="-208" r="2.4" fill="#fff" stroke="${INK}" stroke-width="1.5"/>`;
  const headG=`<g transform="rotate(${f(headRot)} 26 -112)"><path d="${neckD}" stroke="${INK}" stroke-width="20" fill="none" stroke-linecap="round"/><path d="${neckD}" stroke="#fff" stroke-width="14" fill="none" stroke-linecap="round"/><circle cx="38" cy="-174" r="15" fill="${flo?'#fff':'#d8dbe0'}" stroke="${INK}" stroke-width="3"/>${beak}${face}${o.hprop?o.hprop():''}</g>`;
  const prop=o.prop?o.prop():'';
  let inner;
  if(pose==='sit'){
    const bot=-98+30*bh, dy=-bot-3;
    inner=`<g transform="translate(0 ${f(dy)})"><g transform="rotate(-12 0 ${f(bot)})">${legs}${trunk}${headG}${prop}</g></g>`;
  } else if(pose==='swim'){
    inner=`<g transform="rotate(${f(Math.sin(t*3)*2.5)} 0 -98)">${trunk}${headG}${prop}</g>`;
  } else {
    inner=`<g transform="translate(0 ${f(-bob+hop)})">${legs}${trunk}${headG}${prop}</g>`;
  }
  return `<g transform="translate(${f(o.x)} ${f(o.y)}) scale(${f(dir*s)} ${f(s)})" opacity="${o.op==null?1:o.op}">${inner}</g>`;
}
const FLO=o=>lstork(Object.assign({who:'flo'},o));
const MAT=o=>lstork(Object.assign({who:'mat'},o));

/* ---------- DÉCOR ---------- */
function wavePath(y0,amp,k,w,t,x0,x1,bottom,ph=0){
  let d=`M${x0},${bottom} L${x0},${f(y0+amp*Math.sin(k*x0+t*w+ph))}`;
  for(let x=x0;x<=x1;x+=16) d+=` L${x},${f(y0+amp*Math.sin(k*x+t*w+ph))}`;
  return d+` L${x1},${bottom} Z`;
}
let X0=80,X1=1200,VX=0,VY=0,VW=1280,VH=800;const DECK=585;let WB=715;
function card(){
  return `<rect x="${VX}" y="${VY}" width="${VW}" height="${VH}" fill="#0a1a45"/><rect x="${VX+24}" y="${VY+24}" width="${VW-48}" height="${VH-48}" rx="28" fill="${CREAM}"/>`;
}
function badge(txt,y=100,w){w=w||Math.max(110,String(txt).length*12+50);
  return `<rect x="${640-w/2}" y="${y-17}" width="${w}" height="34" rx="17" fill="${NAVY}"/><text x="640" y="${y+6}" text-anchor="middle" font-size="16" font-weight="800" fill="#fff" letter-spacing="1.5">${txt}</text>`;
}
function title(txt,y,size=84){const w=String(txt).length*size*.62,fit=w>VW-120?` textLength="${VW-120}" lengthAdjust="spacingAndGlyphs"`:"";
  return `<text x="640" y="${y}" text-anchor="middle" font-size="${size}" font-weight="800" fill="${NAVY}" letter-spacing="1"${fit}>${txt}</text>`;
}
function block(x){
  return `<g transform="translate(${x} ${DECK})"><rect x="-27" y="-52" width="54" height="52" fill="#f3dfae" stroke="${DARK}" stroke-width="3"/><path d="M-27,-52 L27,0 M27,-52 L-27,0" stroke="${DARK}" stroke-width="2.6"/><path d="M-34,-57 L32,-65 L32,-56 L-34,-48 Z" fill="#2f60d4" stroke="${DARK}" stroke-width="2.6" stroke-linejoin="round"/></g>`;
}
function deckLines(){
  return `<path d="M${X0},${DECK-1} H${X1}" stroke="${DARK}" stroke-width="3"/><path d="M${X0},${DECK+6} H${X1}" stroke="#c9b27a" stroke-width="3"/>`;
}
const CLIPF=()=>`<clipPath id="cw"><rect x="${X0}" y="${VY+24}" width="${X1-X0}" height="${VH-48}" rx="28"/></clipPath>`;
function waterBack(t){
  return `<g clip-path="url(#cw)"><rect x="${X0}" y="${DECK+8}" width="${X1-X0}" height="${WB-DECK-8}" fill="#2a79d6"/><path d="${wavePath(DECK+24,7,0.012,1.6,t,X0,X1,WB)}" fill="#52b6ee"/></g>`;
}
function waterFront(t){
  return `<g clip-path="url(#cw)"><path d="${wavePath(DECK+40,6,0.015,-1.8,t,X0,X1,WB,1.3)}" fill="#2f86de"/><path d="${wavePath(DECK+78,5,0.011,1.2,t,X0,X1,WB,2.1)}" fill="#1b4fb6"/>
  <path d="M${200+30*Math.sin(t)} ${DECK+75} q14,-8 28,0 t28,0" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" opacity=".9"/><path d="M${760+25*Math.sin(t*.8+2)} ${DECK+100} q14,-8 28,0 t28,0" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" opacity=".9"/></g>`;
}

/* ---------- REQUIN ---------- */
function shark(x,y,rot,open,sc=1.3,t=0){
  const hx=150,hy=28; // charnière
  const a=open*Math.PI/180, c=Math.cos(-a), sn=Math.sin(-a);
  const rel=(px,py)=>{const dx=px-hx,dy=py-hy;return [hx+dx*c-dy*sn, hy+dx*sn+dy*c]};
  const lt=rel(5,16);
  const interior=`<path d="M${hx},${hy-4} L0,6 L${f(lt[0])},${f(lt[1])} Z" fill="#7a1230"/><path d="M${hx-8},${hy-2} L${hx-60},${hy-2+ (lt[1]-hy)*0.35} L${hx-20},${hy+ (lt[1]-hy)*0.6} Z" fill="#e0627c" opacity=".85"/>`;
  let teethU='',teethL='';
  for(let i=0;i<8;i++){const px=8+i*17,py=10+(hy-6-10)*(px/hx);teethU+=`<path d="M${px},${f(py)} l7,0 l-3.5,15 Z" fill="#fff" stroke="#c9d3df" stroke-width="1"/>`;}
  for(let i=0;i<7;i++){const px=12+i*18,py=16+(hy-2-16)*(px/hx);teethL+=`<path d="M${px},${f(py)} l7,0 l-3.5,-14 Z" fill="#fff" stroke="#c9d3df" stroke-width="1"/>`;}
  const upper=`<path d="M0,8 C22,-26 100,-56 190,-62 L226,-118 L264,-60 C340,-52 410,-32 462,-38 L526,-92 L508,-6 L530,64 L462,24 C400,42 322,46 244,46 L${hx},${hy-2} L0,8 Z" fill="#6f89ab" stroke="${DARK}" stroke-width="3.5" stroke-linejoin="round"/><path d="M0,8 L${hx},${hy-2} L244,46 C322,46 400,42 462,24 L530,64 L508,-6 L462,-4 C400,18 322,26 244,28 Z" fill="#e9eef5" opacity=".0"/><path d="M12,2 C60,2 100,10 ${hx},${hy-2}" fill="none" stroke="${DARK}" stroke-width="2"/><path d="M246,10 q-12,16 0,34 M262,12 q-12,16 0,32 M278,14 q-12,16 0,30" fill="none" stroke="${DARK}" stroke-width="2.4" opacity=".6"/><circle cx="62" cy="-8" r="9" fill="#fff" stroke="${DARK}" stroke-width="2.5"/><circle cx="59" cy="-7" r="4.2" fill="${DARK}"/><path d="M48,-22 L78,-12" stroke="${DARK}" stroke-width="4.5" stroke-linecap="round"/>`;
  const lower=`<g transform="rotate(${f(-open)} ${hx} ${hy})"><path d="M${hx},${hy-2} L5,16 C8,46 60,72 ${hx},80 C200,84 244,70 252,48 Z" fill="#dfe7f1" stroke="${DARK}" stroke-width="3.5" stroke-linejoin="round"/>${teethL}</g>`;
  const T=`translate(${f(x)} ${f(y)}) rotate(${f(rot)}) scale(${sc})`;
  return {back:`<g transform="${T}">${interior}</g>`, front:`<g transform="${T}">${upper}${teethU}${lower}</g>`};
}

/* ---------- SCÈNE 1 : ÉVACUATION ---------- */
const FIN_T0=1.3, FIN_T1=4.0;
function finDraw(x,y,sc,t,front){
  return `<g transform="translate(${f(x)} ${f(y)}) scale(${f(sc)})"><ellipse cx="8" cy="12" rx="70" ry="9" fill="#1b4fb6" opacity="${front?.35:.5}"/><path d="M-26,4 C-10,-14 6,-34 12,-62 C24,-38 36,-14 48,4 Z" fill="#6f89ab" stroke="${DARK}" stroke-width="3.2" stroke-linejoin="round"/><path d="M-70,8 q36,-12 78,-2 M-48,16 q30,-8 74,-2" fill="none" stroke="#fff" stroke-width="3" opacity=".85" stroke-linecap="round"/></g>`;
}
function finPos(t){
  const th=(t-FIN_T0)*1.9, c=Math.cos(th), sn=Math.sin(th);
  return {x:560+390*c, y:DECK+27+16*sn, sc:1.55+0.5*sn, front:sn>0};
}
function sceneEvac(t,P){
  let o='';
  o+=card()+badge(P.tag||'ÉVACUATION',100);
  o+=title('ÉVACUATION DU BASSIN',186);
  o+=`<text x="640" y="228" text-anchor="middle" font-size="25" font-weight="600" fill="${NAVY}" opacity=".85">Fin de l'échauffement · merci de sortir de l'eau</text>`;
  const rem=Math.max(0,Math.ceil(5.1-t-1e-6));
  const urgent=rem<=2, zero=rem===0;
  const pulse=urgent?(0.5+0.5*Math.sin(t*14)):0;
  const bg=zero?(Math.sin(t*12)>0?'#e2262e':'#8f1017'):(urgent?`rgb(${f(18+190*pulse)},${f(48-10*pulse)},${f(127-80*pulse)})`:NAVY);
  const sc=urgent&&!zero?1+0.04*Math.abs(Math.sin(t*7)):1;
  o+=`<g transform="translate(300 292) scale(${f(sc)})"><rect x="-120" y="-44" width="360" height="88" rx="16" fill="${bg}"/><text x="60" y="-16" text-anchor="middle" font-size="15" font-weight="800" fill="#fff" opacity=".85" letter-spacing="1.5">SORTIE DE L'EAU</text><text x="60" y="26" text-anchor="middle" font-size="44" font-weight="800" fill="#fff">MAINTENANT</text></g>`;
  const tot=5*3600+8*60+25-Math.floor(t);
  const hh=Math.floor(tot/3600), mm=Math.floor(tot%3600/60), ss=tot%60;
  o+=`<rect x="640" y="248" width="410" height="88" rx="16" fill="${NAVY}"/><text x="660" y="300" font-size="14" font-weight="800" fill="#fff" opacity=".85" letter-spacing="1">PREMIER DÉPART DANS</text><text x="935" y="304" text-anchor="middle" font-size="46" font-weight="800" fill="#fff" style="font-variant-numeric:tabular-nums">${P.cd||''}</text><text x="1008" y="322" text-anchor="middle" font-size="13" font-weight="600" fill="#fff" opacity=".8">${P.at?'à '+P.at:''}</text>`;
  o+=block(930)+block(1070);
  o+=waterBack(t)+deckLines();
  // ailerons : derrière les cigognes
  const showFin=t>=FIN_T0&&t<FIN_T1;
  const fp=showFin?finPos(t):null;
  if(showFin&&!fp.front) o+=`<g clip-path="url(#cw)">${finDraw(fp.x,fp.y,fp.sc,t,false)}</g>`;
  // positions
  const FS=1.3, MS_=1.1;
  const mSwimX=lerp(-160,480,ease(t/1.8)), fSwimX=lerp(-460,700,ease(t/2.1));
  const mSwimY=DECK+33+98*MS_+Math.sin(t*3.2)*3, fSwimY=DECK+33+98*FS+Math.sin(t*2.7+1)*3;
  // Mat saute sur le bord
  let mx=mSwimX, my=mSwimY, mpose='swim', ms=MS_;
  if(t>=2.9){
    const hu=clamp((t-2.9)/0.6);
    mx=lerp(480,350,hu); my=lerp(mSwimY,DECK,ease(hu))-Math.sin(hu*Math.PI)*60;
    if(t<3.5){ mpose='fly'; }
    else mpose=(t<5.1?'panic':'stand');
  }
  if(t>=3.5&&t<5.1){ mx=350; my=DECK; }
  if(t>=5.1){ mx=350; my=DECK; }
  // Flo
  let fx=fSwimX, fy=fSwimY, fs=FS, fpose='swim';
  const suck=ease((t-4.5)/0.45);
  if(t>=4.5){ fx=lerp(700,694,suck); fy=lerp(fSwimY,DECK+112,suck); fs=lerp(FS,0.75,suck); }
  const fDead=t>=5.0;
  // requin
  const K=[[4.0,860,760,70,0],[4.3,760,590,52,40],[4.6,680,470,22,64],[4.9,590,468,4,74],[5.0,584,468,4,68],[5.08,580,468,3,0],[5.45,500,520,-24,0],[5.9,430,650,-38,0],[6.25,385,800,-58,0]];
  const sk=keys(t,K,true);
  const showShark=t>=4.0&&t<6.3;
  const SH=showShark?shark(sk[0],sk[1],sk[2],sk[3],1.3,t):null;
  if(SH) o+=`<g clip-path="url(#cw)">${SH.back}</g>`;
  const exc=(x,yy)=>`<g transform="translate(${f(x)} ${f(yy-Math.abs(Math.sin(t*12))*4)})"><circle r="17" fill="#ffe14a" stroke="${DARK}" stroke-width="3"/><text y="8" text-anchor="middle" font-size="24" font-weight="800" fill="${RED}">!</text></g>`;
  o+=MAT({x:mx,y:my,s:ms,t,pose:mpose,dir:1,head:mpose==='stand'?Math.sin(t*2)*3:0,beak:undefined});
  if(!fDead) o+=FLO({x:fx,y:fy,s:fs,t,pose:t>=2.3&&t<4.5?'swim':'swim',dir:1,head:t>=2.3?Math.sin(t*9)*4:0,beak:t>=2.3&&t<4.6?5+6*Math.abs(Math.sin(t*14)):0});
  if(t>=2.3&&t<4.6) o+=exc(fx+75,fy-290);
  if(t>=3.2&&t<5.1) o+=exc(mx+110,DECK-215);
  if(SH) o+=`<g clip-path="url(#cw)">${SH.front}</g>`;
  o+=waterFront(t);
  // remous autour des nageurs
  const ring=(cx,cy,ph,w)=>`<ellipse cx="${f(cx)}" cy="${f(cy)}" rx="${f(w+8*Math.sin(t*3+ph))}" ry="${f(8+2*Math.sin(t*3+ph))}" fill="none" stroke="#fff" stroke-width="3" opacity=".85"/>`;
  o+=`<g clip-path="url(#cw)">`;
  if(t<3.0) o+=ring(mx,DECK+44,0,60);
  if(!fDead&&t<4.7) o+=ring(fx,DECK+48,1.3,78*fs);
  o+=`</g>`;
  if(showFin&&fp.front) o+=`<g clip-path="url(#cw)">${finDraw(fp.x,fp.y,fp.sc,t,true)}</g>`;
  // éclaboussures
  const spl=(cx,t0,n)=>{let s='';const u=t-t0;if(u<0||u>1.1)return '';for(let i=0;i<n;i++){const a=-Math.PI/2+(rnd(i+cx)-0.5)*2.2, v=160+rnd(i*3+cx)*220;const px=cx+Math.cos(a)*v*u, py=DECK+30+Math.sin(a)*v*u+500*u*u;s+=`<circle cx="${f(px)}" cy="${f(py)}" r="${f(6*(1-u*0.6))}" fill="#bfe6ff" stroke="#fff" stroke-width="1.5" opacity="${f(1-u)}"/>`;}return `<g clip-path="url(#cw)">${s}<ellipse cx="${cx}" cy="${DECK+36}" rx="${f(30+u*160)}" ry="${f(6+u*16)}" fill="none" stroke="#fff" stroke-width="3" opacity="${f(1-u)}"/></g>`};
  o+=spl(790,4.1,16)+spl(450,5.45,22);
  // lunettes de Flo + plumes qui flottent
  if(t>5.0){
    const u=t-5.0, fall=clamp(u/0.9);
    const gy=lerp(520,DECK+36,fall*fall)+ (fall>=1?Math.sin(t*2.6)*3:0), gx=690+Math.sin(u*2)*8+(fall>=1?(u-0.9)*5:0);
    o+=`<g clip-path="url(#cw)"><g transform="translate(${f(gx)} ${f(gy)}) rotate(${f(u*200*(1-fall*0.8))})"><circle r="13" fill="rgba(255,255,255,.65)" stroke="#111" stroke-width="3.5"/><path d="M13,0 L40,6" stroke="#111" stroke-width="3.5"/><path d="M-13,-2 L-30,-6" stroke="#111" stroke-width="3.5"/></g></g>`;
    for(let i=0;i<16;i++){
      const t0=rnd(i)*0.35, v=u-t0; if(v<0) continue;
      const x0=620+rnd(i+9)*160, y0=470+rnd(i+4)*80, vx=(rnd(i+2)-0.5)*70;
      const land=DECK+30+rnd(i+6)*34;
      let py=y0+v*v*60+v*40, px=x0+vx*Math.min(v,1.6)+Math.sin(v*3+i)*18*Math.min(1,v);
      let onW=false; if(py>=land){py=land+Math.sin(t*2.2+i)*2.5; px=x0+vx*1.6+ (v-1.2)*6; onW=true;}
      const rot=onW?(i*37%80)-40:(30*Math.sin(v*4+i)+i*20);
      o+=`<g clip-path="url(#cw)"><path d="M-13,0 Q0,-6 13,0 Q0,5 -13,0 Z" fill="#fff" stroke="${DARK}" stroke-width="1.8" transform="translate(${f(px)} ${f(py)}) rotate(${f(rot)})"/></g>`;
    }
  }
  return o;
}
/* ---------- SCÈNE 2 : MÉDAILLES ---------- */
function swimmer(x,by,cap,t,k,medal,age){
  const a=Math.sin(t*6+k*2.1)*13;
  const arm=(sx,aa)=>`<path d="M${sx*13},-46 L${sx*(30+aa*0.3)},${f(-70+aa)} L${sx*(33+aa*0.3)},${f(-94+aa)}" fill="none" stroke="${DARK}" stroke-width="10.5" stroke-linecap="round" stroke-linejoin="round"/><path d="M${sx*13},-46 L${sx*(30+aa*0.3)},${f(-70+aa)} L${sx*(33+aa*0.3)},${f(-94+aa)}" fill="none" stroke="#2a5fd6" stroke-width="5.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${sx*(33+aa*0.3)}" cy="${f(-97+aa)}" r="6" fill="#f6caa3" stroke="${DARK}" stroke-width="2.5"/>`;
  const m={gold:'#f2b81c',silver:'#c7cfd9',bronze:'#cd7f32'}[medal];
  let med='';
  if(age!=null&&age>=0){
    const pop=age<0.3?1+0.9*(1-age/0.3):1;
    let sp='';
    if(age<0.6){for(let i=0;i<8;i++){const an=i*Math.PI/4, r1=12+age*40, r2=r1+8;sp+=`<path d="M${f(Math.cos(an)*r1)},${f(-30+Math.sin(an)*r1)} L${f(Math.cos(an)*r2)},${f(-30+Math.sin(an)*r2)}" stroke="#ffd23f" stroke-width="3" stroke-linecap="round" opacity="${f(1-age/0.6)}"/>`;}}
    med=`<path d="M-9,-52 L0,-32 L9,-52" fill="none" stroke="#fff" stroke-width="3"/><g transform="translate(0 -30) scale(${f(pop)})"><circle r="8" fill="${m}" stroke="${DARK}" stroke-width="2.5"/><circle r="3.5" fill="none" stroke="${DARK}" stroke-width="1.6" opacity=".5"/></g>${sp}`;
  }
  return `<g transform="translate(${x} ${by})">${arm(-1,a)}${arm(1,-a)}<rect x="-18" y="-56" width="36" height="54" rx="9" fill="#2a5fd6" stroke="${DARK}" stroke-width="3.5"/>${med}<circle cx="0" cy="-70" r="16" fill="#f6caa3" stroke="${DARK}" stroke-width="3.5"/><path d="M-16,-72 A16,16 0 0 1 16,-72 Z" fill="${cap}" stroke="${DARK}" stroke-width="3" stroke-linejoin="round"/><circle cx="-5.5" cy="-67" r="1.8" fill="${DARK}"/><circle cx="5.5" cy="-67" r="1.8" fill="${DARK}"/><path d="M-5,-61 q5,5 10,0" fill="none" stroke="${DARK}" stroke-width="2.2" stroke-linecap="round"/></g>`;
}
function step(cx,h,n){
  return `<rect x="${cx-70}" y="${DECK-h}" width="140" height="${h}" fill="#f3e2b8" stroke="${DARK}" stroke-width="3.5"/><text x="${cx}" y="${DECK-h+(h>60?40:30)}" text-anchor="middle" font-size="${h>60?38:26}" font-weight="800" fill="${NAVY}">${n}</text>`;
}
function confetti(u){
  let s='';const cols=['#ffd23f','#ff7a2f','#3fd1c7','#e2493f','#6aa0ff','#8b5cf6'];
  for(let i=0;i<70;i++){
    const t0=2.3+rnd(i)*1.2; if(u<t0) continue;
    const v=70+rnd(i+5)*90, x=100+rnd(i+11)*1080+Math.sin((u-t0)*3+i)*20;
    const y=60+((u-t0)*v)%(DECK-70-60+10);
    if(y>DECK) continue;
    s+=`<rect x="${f(x)}" y="${f(y)}" width="9" height="5" fill="${cols[i%6]}" transform="rotate(${f((u*200+i*37)%360)} ${f(x)} ${f(y)})"/>`;
  }
  return s;
}
function medalBeak(col){
  const c={gold:'#f2b81c',silver:'#c7cfd9',bronze:'#cd7f32'}[col];
  return ()=>`<g><path d="M94,-168 L90,-140" stroke="${NAVY}" stroke-width="5" stroke-linecap="round"/><circle cx="89" cy="-132" r="10" fill="${c}" stroke="${DARK}" stroke-width="3"/><circle cx="89" cy="-132" r="4" fill="none" stroke="${DARK}" stroke-width="1.8" opacity=".5"/></g>`;
}
function sceneMedal(u,P){
  let o=card()+badge('CÉRÉMONIE PROTOCOLAIRE',100,330)+title('REMISE DES MÉDAILLES',186,70);if(P.sub)o+=`<text x="640" y="228" text-anchor="middle" font-size="25" font-weight="600" fill="${NAVY}" opacity=".85">${P.sub}</text>`;if(P.cd)o+=`<text x="640" y="${P.sub?266:232}" text-anchor="middle" font-size="28" font-weight="800" fill="${NAVY}">Reprise dans ${P.cd}${P.at?' · à '+P.at:''}</text>`;
  o+=`<defs>${CLIPF()}</defs>`;
  o+=waterBack(u*1.0)+deckLines();
  const G={b:1.5,s:2.8,g:4.5};
  const age=k=>u>=G[k]?u-G[k]:null;
  const dip=(a,b)=>u>=a&&u<=b?Math.sin((u-a)/(b-a)*Math.PI)*24:0;
  o+=`<g transform="translate(640 ${DECK}) scale(1.3) translate(-640 ${-DECK})">`;
  o+=step(590,56,2)+step(730,92,1)+step(870,40,3);
  o+=swimmer(590,DECK-56,'#ffd23f',u,0,'silver',age('s'))+swimmer(700,DECK-92,'#ff7a2f',u,1,'gold',age('g'))+swimmer(870,DECK-40,'#3fd1c7',u,2,'bronze',age('b'));
  // Flo : médaille de bronze, puis or
  let fx,fy,fp='stand',fprop=null,fclap=false;
  if(u<1.1){ fx=lerp(1150,985,u/1.1); fy=DECK; fp='walk'; }
  else if(u<3.0){ fx=985; fy=DECK; }
  else if(u<3.8){ const e=(u-3.0)/0.8; fx=lerp(985,775,ease(e)); fy=lerp(DECK,DECK-92,ease(e))-Math.sin(e*Math.PI)*90; fp='fly'; }
  else { fx=775; fy=DECK-92; }
  if(u<1.5) fprop=medalBeak('bronze'); else if(u>=3.0&&u<4.5) fprop=medalBeak('gold');
  fclap=(u>=1.6&&u<3.0)||u>=4.6;
  const fhead=dip(1.1,1.5)||dip(4.05,4.5);
  o+=FLO({x:fx,y:fy,s:0.74,t:u,pose:fp,dir:-1,clap:fclap,head:fhead||(fp==='stand'?Math.sin(u*2.5)*3:0),hprop:fprop});
  // Mat : médaille d'argent
  let mx=250, mp='stand';
  if(u>=1.2&&u<2.4){ mx=lerp(250,490,ease((u-1.2)/1.2)); mp='walk'; } else if(u>=2.4) mx=490;
  const mprop=u<2.8?medalBeak('silver'):null;
  o+=MAT({x:mx,y:DECK,s:0.6,t:u,pose:mp,dir:1,clap:u>=3.0,head:dip(2.4,2.8)||(mp==='stand'?Math.sin(u*2)*3:0),hprop:mprop});
  o+='</g>';
  o+=confetti(u-2.1);
  o+=waterFront(u);
  return o;
}

/* ---------- SCÈNE 3 : PAUSE ---------- */
function chair(){
  const fr=(a,b,c,d)=>`<path d="M${a},${b} L${c},${d}" stroke="${DARK}" stroke-width="5" stroke-linecap="round"/>`;
  const P="M-52,-112 L0,-48 L100,-38";
  return `${fr(-52,-112,-30,0)}${fr(0,-48,26,0)}${fr(100,-38,86,0)}${fr(-52,-112,60,-10)}
  <path d="${P}" fill="none" stroke="${DARK}" stroke-width="26" stroke-linecap="round" stroke-linejoin="round"/>
  <path d="${P}" fill="none" stroke="#2f60d4" stroke-width="20" stroke-linecap="round" stroke-linejoin="round"/>
  <path d="${P}" fill="none" stroke="#fff" stroke-width="20" stroke-dasharray="11 11" stroke-linejoin="round"/>`;
}
function newspaper(t){
  const ph=t%3.2, bump=ph>2.8?Math.sin((ph-2.8)/0.4*Math.PI):0, sx=1-0.92*bump;
  return ()=>{
    let lines='';for(let i=0;i<6;i++)lines+=`<path d="M-20,${-20+i*8} h${i%3==2?26:40}" stroke="#7a86a8" stroke-width="2.6" stroke-linecap="round"/>`;
    return `<g transform="translate(98 -102) rotate(-7)"><g transform="scale(${f(sx)} 1)"><rect x="-28" y="-36" width="56" height="72" rx="3" fill="#fff" stroke="${DARK}" stroke-width="3"/><rect x="-21" y="-31" width="42" height="9" fill="${NAVY}"/>${lines}</g><ellipse cx="-31" cy="8" rx="8" ry="12" fill="#1c1f2b" stroke="${DARK}" stroke-width="2.5"/><ellipse cx="31" cy="8" rx="8" ry="12" fill="#1c1f2b" stroke="${DARK}" stroke-width="2.5"/></g>`;
  };
}
function cocktail(t){
  return ()=>`<g transform="translate(104 -108)"><path d="M0,0 L4,-44" stroke="#fff" stroke-width="6" stroke-linecap="round"/><path d="M0,0 L4,-44" stroke="${RED}" stroke-width="6" stroke-linecap="round" stroke-dasharray="6 6"/><path d="M-17,-4 L19,-4 L2,20 Z" fill="#ff9d2e" stroke="${DARK}" stroke-width="3" stroke-linejoin="round"/><path d="M-12,-4 L14,-4 L11,2 L-9,2 Z" fill="#ffd76b" opacity=".8"/><path d="M2,20 V40 M-10,41 H14" stroke="${DARK}" stroke-width="3.4" stroke-linecap="round"/><circle cx="-17" cy="-4" r="8" fill="#ffe96b" stroke="${DARK}" stroke-width="2.4"/><path d="M-17,-12 V4 M-25,-4 H-9" stroke="${DARK}" stroke-width="1.4" opacity=".6"/><path d="M-6,-12 L-14,-28 L4,-20 Z" fill="#f45b9a" stroke="${DARK}" stroke-width="2" stroke-linejoin="round" transform="translate(6 2)"/></g>`;
}
function parasol(x,t){
  const sway=Math.sin(t*1.2)*1.2;
  let seg='';const cols=['#e2493f','#fff'];
  for(let i=0;i<6;i++){const x0=-150+i*50;seg+=`<path d="M${x0},0 Q${x0+25},-14 ${x0+50},0 Q${x0+36},-60 0,-110 Q${x0-14},-60 ${x0},0 Z" fill="${cols[i%2]}" opacity="0"/>`;}
  return `<g transform="translate(${x} ${DECK}) rotate(${f(sway)})"><path d="M0,0 V-270" stroke="${DARK}" stroke-width="7" stroke-linecap="round"/><g transform="translate(0 -270)"><path d="M-170,0 A170,78 0 0 1 170,0 Z" fill="#fff" stroke="${DARK}" stroke-width="4" stroke-linejoin="round"/><path d="M-170,0 A170,78 0 0 1 -113,-57 L-57,0 Z M0,0 L0,-78 L57,0 Z M113,-57 A170,78 0 0 1 170,0 L57,0 Z" fill="#e2493f" opacity=".95"/><path d="M-170,0 Q-142,16 -113,0 Q-85,16 -57,0 Q-28,16 0,0 Q28,16 57,0 Q85,16 113,0 Q142,16 170,0" fill="#fff" stroke="${DARK}" stroke-width="3"/></g></g>`;
}
function scenePause(u,P){
  let o=card()+badge('PAUSE',100,100)+title(P.title||'PAUSE',186,84);
  o+=`<text x="640" y="228" text-anchor="middle" font-size="26" font-weight="${P.cd?800:600}" fill="${NAVY}" opacity=".85">${P.cd?'Reprise dans '+P.cd+(P.at?' · à '+P.at:''):(P.sub||'La compétition reprend dans quelques instants')}</text>`;
  // soleil
  o+=`<g transform="translate(1110 130) rotate(${f(u*12)})">`;for(let i=0;i<12;i++)o+=`<path d="M0,-44 L0,-58" stroke="#ffc83a" stroke-width="6" stroke-linecap="round" transform="rotate(${i*30})"/>`;o+=`<circle r="32" fill="#ffd23f" stroke="#f0a91e" stroke-width="4"/></g>`;
  o+=`<defs>${CLIPF()}</defs>`+block(1000)+block(1120);
  o+=waterBack(u)+deckLines();
  o+=parasol(430,u);
  // Flo (lecture)
  o+=`<g transform="translate(215 ${DECK}) scale(1.22)">${chair()}${lstork({who:'flo',x:14,y:-56,s:1,pose:'sit',t:u,head:22,prop:newspaper(u)})}</g>`;
  // Matthieu (cocktail)
  const sip=Math.max(0,Math.sin(u*1.7));
  o+=`<g transform="translate(555 ${DECK}) scale(1.0)">${chair()}${lstork({who:'mat',gogglesDown:true,x:14,y:-56,s:0.95,pose:'sit',t:u,head:12*sip,prop:cocktail(u)})}</g>`;
  o+=waterFront(u);
  // petites bulles zZ
  return o;
}


/* ---------- LECTEUR SWIM DIRECT ---------- */
window.MFA={render(svg,mode,P,t,w,h){const r=w/h||1.6;
  if(r<1.6){VW=1280;VH=1280/r;VX=0;VY=(800-VH)*.6}else{VH=800;VW=800*r;VY=0;VX=(1280-VW)/2}
  X0=VX+24;X1=VX+VW-24;WB=VY+VH-24;
  svg.setAttribute("viewBox",`${f(VX)} ${f(VY)} ${f(VW)} ${f(VH)}`);
  let o=`<defs>${CLIPF()}</defs>`;
  if(mode==="evac")o+=sceneEvac(t%8.2,P);else if(mode==="cer")o+=sceneMedal(t%7.5,P);else o+=scenePause(t%3600,P);
  svg.innerHTML=o}};

})();
